73	    @Test
74	    void 主流程_登记发布拉取回执成功并更新设备版本() throws Exception {
75	        mockMvc.perform(post("/api/devices").contentType("application/json").content("""
76	                        {"requestId":"r1","deviceId":"d1","model":"m1","currentVersion":"1.0.0","bucketNo":5}
77	                        """))
