98	                    return e;
99	                }
100	            }));
101	        }
102	        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
103	        start.countDown();
104	        List<Object> results = new ArrayList<>();
105	        for (Future<Object> future : futures) {
