2	
3	import jakarta.validation.constraints.Max;
4	import jakarta.validation.constraints.Min;
5	import jakarta.validation.constraints.NotBlank;
6	import jakarta.validation.constraints.Size;
7	
8	/**
9	 * 创建发布单请求。sampleFloor 与 failureThresholdPercent 为可选，
10	 * 缺省分别为 2 与 100（即仅当本轮全部失败且样本达标时才自动暂停），旧客户端不传仍可创建。
11	 */
12	public record CreateReleaseRequest(
13	        @NotBlank @Size(max = 64) String requestId,
14	        @NotBlank @Size(max = 64) String model,
15	        @NotBlank @Size(max = 64) String fromVersion,
16	        @NotBlank @Size(max = 64) String toVersion,
17	        @Min(0) @Max(100) int ratio,
18	        @Min(2) @Max(100) Integer sampleFloor,
19	        @Min(1) @Max(100) Integer failureThresholdPercent) {
20	
21	    public static final int DEFAULT_SAMPLE_FLOOR = 2;
22	    public static final int DEFAULT_FAILURE_THRESHOLD_PERCENT = 100;
23	
24	    /**
